require_once __DIR__.'/../../includes/accounting_ui.php';acHandle(function()use($ac){$id=(int)($_POST['expense_id']??0);return match($_POST['action']??''){'create'=>$ac->createExpense($_POST),'approve'=>$ac->approveExpense($id),'pay'=>$ac->payExpense($id,$_POST['date']??''),'reverse'=>$ac->reverseExpense($id,$_POST['date']??'',$_POST['reason']??'',!empty($_POST['confirm'])),default=>throw new InvalidArgumentException('Unsupported expense action.')};},'expenses');
$accounts=$ac->rows('SELECT * FROM ac_accounts WHERE school_id=? AND is_active=1 ORDER BY code',[$school]);ob_start();
?>
<p class="text-muted">Draft → administrator approval (expense/payable posting) → payment (cash/bank posting). Each action posts exactly once.</p>
<?php if($ac->can('expense')): ?><details class="mb-3"><summary class="btn btn-primary">Add expense</summary><?php acForm('create'); ?><div class="row"><div class="col-md-6"><?php acInput('title','Expense title');acInput('payee','Vendor / payee','','text',false);acInput('amount','Amount (NPR)','0.00','number');acInput('expense_date','Expense date',date('Y-m-d'),'date'); ?></div><div class="col-md-6"><?php acSelect('expense_account_id','Expense account',array_values(array_filter($accounts,fn($a)=>$a['type']==='expense')),$ac->control('expense'));acSelect('payment_account_id','Cash / bank account',array_values(array_filter($accounts,fn($a)=>$a['type']==='asset'&&(!$a['control_key']||in_array($a['control_key'],['cash','bank'],true)))),$ac->control('cash'));acInput('reference','Vendor bill reference','','text',false);acInput('remarks','Description / remarks','','text',false); ?></div></div><?php acSubmit('Save expense draft'); ?></details><?php endif; ?>
<div class="card card-body table-responsive"><table class="table"><thead><tr><th>Expense</th><th>Date</th><th>Payee</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($ac->rows('SELECT * FROM ac_expenses WHERE school_id=? ORDER BY id DESC LIMIT 100',[$school]) as $e): ?><tr><td><?= sanitize($e['number'].' · '.$e['title']) ?></td><td><?= sanitize(schoolDateLabel($e['expense_date'],'both','ymd')) ?></td><td><?= sanitize($e['payee']) ?></td><td><?= acMoney((int)$e['amount_minor']) ?></td><td><?= sanitize($e['status']) ?></td><td><?php if($e['status']==='draft'&&$ac->can('approve')): ?><form method="post"><input type="hidden" name="action" value="approve"><input type="hidden" name="expense_id" value="<?= $e['id'] ?>"><button class="btn btn-sm btn-primary">Approve expense</button></form><?php elseif($e['status']==='approved'&&$ac->can('expense')): ?><form method="post"><input type="hidden" name="action" value="pay"><input type="hidden" name="expense_id" value="<?= $e['id'] ?>"><input type="date" name="date" value="<?= date('Y-m-d') ?>" required><button class="btn btn-sm btn-primary">Record payment</button></form><?php endif; ?><?php if(in_array($e['status'],['approved','paid'],true)&&$ac->can('reverse')): ?><details><summary>Reverse</summary><form method="post"><input type="hidden" name="action" value="reverse"><input type="hidden" name="expense_id" value="<?= $e['id'] ?>"><?php acInput('date','Reversal date',date('Y-m-d'),'date');acInput('reason','Reason'); ?><label><input type="checkbox" name="confirm" value="1" required> Confirm reversal</label><button class="btn btn-sm btn-danger">Reverse expense</button></form></details><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php acRender('Expenses',ob_get_clean());
